        if(method=="openPinnedInputLeases")return ActiveBrokerState.OpenPins();
        if(method=="revalidatePinnedInputLeases")return ActiveBrokerState.RevalidatePins();
        if(method=="allocateOwnedRoot")return ActiveBrokerState.AllocateRoot();
        if(method=="createOwnershipLedger")return ActiveBrokerState.CreateLedger();
        if(method=="runOwnedProcess")return ActiveBrokerState.RunProcess(requestPayload,operationId,cancellation);
