        else if(method=="captureGlobalMutationSnapshot")payload.RequireKeys();
        else if(method=="revalidatePinnedInputLeases")payload.RequireKeys("leaseId","recordsSha256");
        else if(method=="allocateOwnedRoot")payload.RequireKeys("precreatedRootLeaseId");
        else if(method=="createOwnershipLedger")payload.RequireKeys("rootLeaseId");
        else if(method=="runOwnedProcess")payload.RequireKeys("processRole","fixtureId","executableIdentitySha256","rootLeaseId","ledgerId","pinnedLeaseId","timeoutMs","combinedOutputCapBytes");
        else if(method=="forceStopOwnedProcessTree")payload.RequireKeys("targetOperationId","bindingStateSha256");
        else if(method=="performCleanupStep")payload.RequireKeys("operation","bindingStateSha256");
        else throw new InvalidOperationException("ADAPTER_PROTOCOL_INVALID");
    }

